typedef float rational_t;

class vector3d
{
public:
  typedef rational_t T;
  T x,y,z;

  inline vector3d() {}
  inline vector3d(const vector3d& v) { x = v.x; y = v.y; z = v.z; }
  inline vector3d(T _x, T _y, T _z) { x = _x; y = _y; z = _z; }
  inline vector3d& operator = (const vector3d& v)
  { x = v.x; y = v.y; z = v.z; return *this; }
  inline vector3d& operator -= (const vector3d& v)
  { x -= v.x; y -= v.y; z -= v.z; return *this; }
};

inline vector3d operator - (const vector3d& a, const vector3d& b)
{ return vector3d(a.x - b.x, a.y - b.y, a.z - b.z); }

inline vector3d operator + (const vector3d& a, const vector3d& b)
{ return vector3d(a.x + b.x, a.y + b.y, a.z + b.z); }

inline vector3d operator * (const vector3d& a, vector3d::T d)
{ return vector3d(d * a.x, d * a.y, d * a.z); }

inline vector3d operator * (vector3d::T d, const vector3d& a)
{ return vector3d(d * a.x, d * a.y, d * a.z); }

extern const vector3d ZVEC;
extern const vector3d ZEROVEC;

enum WavePerturbType
{
  WAVE_PerturbTypeTongue = 4,
  WAVE_PerturbTypeBigTongue = 5
};

struct WaveBreakInfoStruct
{
  int onoff;
  WavePerturbType type;
};

class PhysicsObjectClass
{
public:
  char pad[0x20];
  vector3d pos;
};

class SurfBoardObjectClass
{
public:
  char pad_000[0x04];
  PhysicsObjectClass *rb;
  char pad_008[0xE8];
  int lip_jump;
  char pad_0F4[0x04];
  int float_jump;
  char pad_0FC[0x0C];
  int exit_jump;
  char pad_10C[0x10];
  WaveBreakInfoStruct wave_info;
  char pad_124[0x980];
  vector3d float_pos;

  void CorrectLipError(vector3d &pos, float dt);
  bool TongueEffectOn(void) { return (wave_info.onoff && ((wave_info.type == WAVE_PerturbTypeBigTongue)
														|| (wave_info.type == WAVE_PerturbTypeTongue))); }
};

void SurfBoardObjectClass::CorrectLipError(vector3d &pos, float dt)
{
	if (lip_jump && float_jump && !exit_jump)
	{
		vector3d delta = -0.5f*ZVEC;
		if (TongueEffectOn())
		{
			delta = ZEROVEC;
		}

		vector3d vec1 = rb->pos - (float_pos + delta);
		vec1.y = 0.0f;
		//vec1.normalize();
		rb->pos -= vec1*dt*4.0f;
		pos = rb->pos;
	}

}
